#!/bin/bash
# Iterative FAC patch probes, experiments 1 and 2, for the kaiju dev runner. Every
# line is an independent job; run each from this directory with the underworld3
# overlay built from probe/iterative-patch (see README.md). OMP_NUM_THREADS=1.
set -u
cd "$(dirname "$0")"
mkdir -p records logs
export OMP_NUM_THREADS=1

# experiment 1: inexact block solves, one structural block (cut 0) and pieces of 2000 rows (cut 1)
